// Do not edit this file as it will be overwritten if HAMR codegen is rerun

//! C-interface for the component.
//! This code must be unsafe.
//! Assumptions about correctness are introduced and need to be verified by other means.

use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn get_healthy(value: *mut bool) -> bool;
  fn get_echo(value: *mut i32) -> bool;
  fn get_alert_result(value: *mut bool) -> bool;
  fn get_ack() -> bool;
}

pub fn unsafe_get_healthy() -> bool
{
  unsafe {
    let value: *mut bool = &mut false;
    get_healthy(value);
    return *value;
  }
}

pub fn unsafe_get_echo() -> Option<i32>
{
  unsafe {
    let value: *mut i32 = &mut 0;
    if (get_echo(value)) {
      return Some(*value);
    } else {
      return None;
    }
  }
}

pub fn unsafe_get_alert_result() -> Option<bool>
{
  unsafe {
    let value: *mut bool = &mut false;
    if (get_alert_result(value)) {
      return Some(*value);
    } else {
      return None;
    }
  }
}

pub fn unsafe_get_ack() -> bool
{
  unsafe {
    return get_ack();
  }
}

//////////////////////////////////////////////////////////////////////////////////
// Testing Versions
//////////////////////////////////////////////////////////////////////////////////

#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_healthy: Mutex<Option<bool>> = Mutex::new(None);
  pub static ref IN_echo: Mutex<Option<i32>> = Mutex::new(None);
  pub static ref IN_alert_result: Mutex<Option<bool>> = Mutex::new(None);
  pub static ref IN_ack: Mutex<Option<u8>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_healthy.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_echo.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_alert_result.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_ack.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_healthy(value: *mut bool) -> bool
{
  unsafe {
    let guard = IN_healthy.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn get_echo(value: *mut i32) -> bool
{
  unsafe {
    match *IN_echo.lock().unwrap_or_else(|e| e.into_inner()) {
      Some(v) => {
        *value = v;
        return true;
      },
      None => return false,
    }
  }
}

#[cfg(test)]
pub fn get_alert_result(value: *mut bool) -> bool
{
  unsafe {
    match *IN_alert_result.lock().unwrap_or_else(|e| e.into_inner()) {
      Some(v) => {
        *value = v;
        return true;
      },
      None => return false,
    }
  }
}

#[cfg(test)]
pub fn get_ack() -> bool
{
  unsafe {
    match *IN_ack.lock().unwrap_or_else(|e| e.into_inner()) {
      Some(v) => {
        return true;
      },
      None => return false,
    }
  }
}
